CREATE OR REPLACE PROCEDURE sp(
  para_Age NUMBER,
  para_Name VARCHAR2,
  para_Party VARCHAR2,
  para_Home_city VARCHAR2
) AS
  CURSOR c_driver IS
    SELECT * FROM driver
    WHERE Age > para_Age AND Party = para_Party
    FOR UPDATE;
  v_driver driver%ROWTYPE;
BEGIN
  OPEN c_driver;
  LOOP
    FETCH c_driver INTO v_driver;
    EXIT WHEN c_driver%NOTFOUND;
    UPDATE driver SET Name = para_Name WHERE CURRENT OF c_driver;
  END LOOP;
  CLOSE c_driver;

  DELETE FROM driver WHERE Party IS NULL;

  UPDATE driver SET Home_city = para_Home_city;

  UPDATE school_bus
  SET Years_Working = Years_Working + 1
  WHERE Driver_ID IN (SELECT Driver_ID FROM driver WHERE Party = para_Party);

END sp;
